import{_ as s,a0 as l,w as o,s as u,ao as p,I as t,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux 容器輕鬆應對性能工程 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 容器輕鬆應對性能工程 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 容器輕鬆應對性能工程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 容器輕鬆應對性能工程 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170201 Performance made easy with Linux containers","title":"Linux 容器輕鬆應對性能工程","tag":"201708","desc":""},"relativePath":"201708/20170201 Performance made easy with Linux containers.md","filePath":"[post].md"}'),m={name:"201708/20170201 Performance made easy with Linux containers.md"};function d(f,r,S,x,b,y){const a=l("Link");return o(),u("div",null,[r[21]||(r[21]=p('<h1 id="linux-容器輕鬆應對性能工程" tabindex="-1">Linux 容器輕鬆應對性能工程 <a class="header-anchor" href="#linux-容器輕鬆應對性能工程" aria-label="Permalink to “Linux 容器輕鬆應對性能工程”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/containers_scale_performance.jpg?itok=A9RwUOXA" alt="Performance made easy with Linux containers" title="Performance made easy with Linux containers"> 圖片來源： CC0 Public Domain</p><p>應用程序的性能決定了軟件能多快完成預期任務。這回答有關應用程序的幾個問題，例如：</p><ul><li>峯值負載下的響應時間</li><li>與替代方案相比，它易於使用，受支持的功能和用例</li><li>運營成本（CPU 使用率、內存需求、數據吞吐量、帶寬等）</li></ul><p>該性能分析的價值超出了服務負載所需的計算資源或滿足峯值需求所需的應用實例數量的估計。性能顯然與成功企業的基本要素掛鈎。它揭示了用户的總體體驗，包括確定什麼會拖慢客户預期的響應時間，通過設計滿足帶寬要求的內容交付來提高客户粘性，選擇最佳設備，最終幫助企業發展業務。</p><h3 id="問題" tabindex="-1">問題 <a class="header-anchor" href="#問題" aria-label="Permalink to “問題”">​</a></h3><p>當然，這是對業務服務的性能工程價值的過度簡化。為了理解在完成我剛剛所描述事情背後的挑戰，讓我們把它放到一個真實的稍微有點複雜的場景中。</p><p><img src="https://opensource.com/sites/default/files/cloud_scale_performance.jpg" alt="Cloud scale performance" title="Cloud scale performance"></p><p>現實世界的應用程序可能託管在雲端。應用程序可以利用非常大（或概念上是無窮大）的計算資源。在硬件和軟件方面的需求將通過雲來滿足。從事開發工作的開發人員將使用雲交付功能來實現更快的編碼和部署。雲託管不是免費的，但成本開銷與應用程序的資源需求成正比。</p><p>除了<ruby>搜索即服務<rt>Search as a Service</rt></ruby>（SaaS）、<ruby>平台即服務<rt>Platform as a Service</rt></ruby>（PaaS）、<ruby>基礎設施即服務<rt>Infrastructure as a Service</rt></ruby>（IaaS）以及<ruby>負載平衡即服務<rt>Load Balancing as a Service</rt></ruby>（LBaaS）之外，當雲端管理託管程序的流量時，開發人員可能還會使用這些快速增長的雲服務中的一個或多個：</p><ul><li><ruby>安全即服務<rt>Security as a Service</rt></ruby> （SECaaS），可滿足軟件和用户的安全需求</li><li><ruby>數據即服務<rt>Data as a Service</rt></ruby> （DaaS），為應用提供了用户需求的數據</li><li><ruby>登錄即服務<rt>Logging as a Service</rt></ruby> （LaaS），DaaS 的近親，提供了日誌傳遞和使用的分析指標</li><li><ruby>搜索即服務<rt>Search as a Service</rt></ruby> （SaaS），用於應用程序的分析和大數據需求</li><li><ruby>網絡即服務<rt>Network as a Service</rt></ruby> （NaaS），用於通過公共網絡發送和接收數據</li></ul><p>雲服務也呈指數級增長，因為它們使得開發人員更容易編寫複雜的應用程序。除了軟件複雜性之外，所有這些分佈式組件的相互作用變得越來越多。用户羣變得更加多元化。該軟件的需求列表變得更長。對其他服務的依賴性變大。由於這些因素，這個生態系統的缺陷會引發性能問題的多米諾效應。</p><p>例如，假設你有一個精心編寫的應用程序，它遵循安全編碼實踐，旨在滿足不同的負載要求，並經過徹底測試。另外假設你已經將基礎架構和分析工作結合起來，以支持基本的性能要求。在系統的實現、設計和架構中建立性能標準需要做些什麼？軟件如何跟上不斷變化的市場需求和新興技術？如何測量關鍵參數以調整系統以獲得最佳性能？如何使系統具有彈性和自我恢復能力？你如何更快地識別任何潛在的性能問題，並儘早解決？</p><h3 id="進入容器" tabindex="-1">進入容器 <a class="header-anchor" href="#進入容器" aria-label="Permalink to “進入容器”">​</a></h3>',14)),t("p",null,[r[2]||(r[2]=e("軟件",-1)),i(a,{href:"https://opensource.com/resources/what-are-linux-containers"},{default:n(()=>[...r[0]||(r[0]=[e("容器",-1)])]),_:1}),r[3]||(r[3]=e("以",-1)),i(a,{href:"https://opensource.com/resources/what-are-microservices"},{default:n(()=>[...r[1]||(r[1]=[e("微服務",-1)])]),_:1}),r[4]||(r[4]=e("設計或面向服務的架構（SoA）的優點為基礎，提高了性能，因為包含更小的、自足的代碼塊的系統更容易編碼，對其它系統組件有更清晰、定義良好的依賴。測試更容易，包括圍繞資源利用和內存過度消耗的問題比在宏架構中更容易確定。",-1))]),r[22]||(r[22]=t("p",null,"當擴容系統以增加負載能力時，容器應用程序的複製快速而簡單。安全漏洞能更好地隔離。補丁可以獨立版本化並快速部署。性能監控更有針對性，測量更可靠。你還可以重寫和“改版”資源密集型代碼，以滿足不斷變化的性能要求。",-1)),t("p",null,[r[6]||(r[6]=e("容器啓動快速，停止也快速。它比虛擬機（VM）有更高效資源利用和更好的進程隔離。容器沒有空閒內存和 CPU 閒置。它們允許多個應用程序共享機器，而不會丟失數據或性能。容器使應用程序可移植，因此開發人員可以構建並將應用程序發送到任何支持容器技術的 Linux 服務器上，而不必擔心性能損失。容器生存在其內，並遵守其集羣管理器（如 Cloud Foundry 的 Diego、",-1)),i(a,{href:"https://opensource.com/resources/what-is-kubernetes"},{default:n(()=>[...r[5]||(r[5]=[e("Kubernetes",-1)])]),_:1}),r[7]||(r[7]=e("、Apache Mesos 和 Docker Swarm）所規定的配額（比如包括存儲、計算和對象計數配額）。",-1))]),r[23]||(r[23]=t("p",null,[e("容器在性能方面表現出色，而即將到來的 “serverless” 計算（也稱為"),t("ruby",null,[e("功能即服務"),t("rt",null,"Function as a Service")]),e("（FaaS））的浪潮將擴大容器的優勢。在 FaaS 時代，這些臨時性或短期的容器將帶來超越應用程序性能的優勢，直接轉化為在雲中託管的間接成本的節省。如果容器的工作更快，那麼它的壽命就會更短，而且計算量負載純粹是按需的。")],-1)),r[24]||(r[24]=t("hr",null,null,-1)),r[25]||(r[25]=t("p",null,"作者簡介：",-1)),r[26]||(r[26]=t("p",null,"Garima 是 Red Hat 的工程經理，專注於 OpenShift 容器平台。在加入 Red Hat 之前，Garima 幫助 Akamai Technologies＆MathWorks Inc. 開創了創新。",-1)),r[27]||(r[27]=t("hr",null,null,-1)),t("p",null,[r[9]||(r[9]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/17/2/performance-container-world"},{default:n(()=>[...r[8]||(r[8]=[e("https://opensource.com/article/17/2/performance-container-world",-1)])]),_:1})]),t("p",null,[r[13]||(r[13]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/garimavsharma"},{default:n(()=>[...r[10]||(r[10]=[e("Garima",-1)])]),_:1}),r[14]||(r[14]=e(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...r[11]||(r[11]=[e("geekpi",-1)])]),_:1}),r[15]||(r[15]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...r[12]||(r[12]=[e("wxy",-1)])]),_:1})]),t("p",null,[r[18]||(r[18]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...r[16]||(r[16]=[e("LCTT",-1)])]),_:1}),r[19]||(r[19]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...r[17]||(r[17]=[e("Linux中國",-1)])]),_:1}),r[20]||(r[20]=e(" 榮譽推出",-1))])])}const g=s(m,[["render",d]]);export{T as __pageData,g as default};
